mapper.select:
SELECT o.id, o.biz_root_id, o.company_id, o.cargo_order_no, o.shipment_codes, o.po_nos, o.marks, o.external_order_no, o.order_source, o.customer_id, o.customer_name, o.business_type_id, o.business_type_name, o.channel_id, o.channel_name, o.platform_id, o.platform_name, o.customer_service_id, o.customer_service_name, o.container_no, o.inbound_warehouse_id, o.inbound_warehouse_name, o.address_type, o.platform_warehouse_code, o.consignee_name, o.city, o.state, o.zip_code, o.country, o.parcel_carrier_name, o.parcel_tracking_no, o.transfer_flag, o.transfer_warehouse_code, o.forecast_qty_unit, o.declared_carton_qty, o.declared_pallet_qty, o.declared_weight, o.declared_cbm, o.actual_carton_qty, o.actual_pallet_qty, o.actual_weight, o.actual_cbm, o.pre_outbound_flag, o.pre_outbound_no, o.pre_outbound_status, o.outbound_batch_no, o.outbound_order_status, o.outbound_order_time, o.hold_flag, o.hold_status, o.hold_type, o.hold_reason, o.hold_time, o.hold_user_id, o.hold_user_name, o.release_time, o.order_status, COALESCE(br.current_node, o.fulfillment_status) AS fulfillment_status, o.appointment_status, o.pod_status, o.billing_status, o.attachment_count, o.pod_attachment_count, o.exception_attachment_count, o.latest_attachment_time, o.parent_order_id, o.parent_order_no, o.root_order_id, o.root_order_no, o.split_flag, o.split_role, o.split_status, o.split_group_no, o.child_order_count, o.split_source, o.customer_visible_flag, o.earliest_dw_time, o.eta, o.ata, o.actual_arrival_time, o.actual_inbound_time, o.delivery_appointment_time, o.actual_outbound_time, o.signed_time, o.exception_flag, o.exception_count, o.group_code, o.create_time FROM oms_cargo_order o LEFT JOIN biz_root br ON br.id = o.biz_root_id AND br.deleted = 0 WHERE o.deleted = 0
AND o.cargo_order_no LIKE CONCAT('%', #{bo.keyword}, '%')
AND (o.marks LIKE CONCAT('%', #{bo.keyword}, '%') OR EXISTS ( SELECT 1 FROM oms_cargo_order_shipment s WHERE s.cargo_order_id = o.id AND s.deleted = 0 AND s.shipping_mark LIKE CONCAT('%', #{bo.keyword}, '%') ))
AND (o.shipment_codes LIKE CONCAT('%', #{bo.keyword}, '%') OR EXISTS ( SELECT 1 FROM oms_cargo_order_shipment s WHERE s.cargo_order_id = o.id AND s.deleted = 0 AND s.shipment_no LIKE CONCAT('%', #{bo.keyword}, '%') ))
AND (o.po_nos LIKE CONCAT('%', #{bo.keyword}, '%') OR EXISTS ( SELECT 1 FROM oms_cargo_order_shipment s WHERE s.cargo_order_id = o.id AND s.deleted = 0 AND s.po_no LIKE CONCAT('%', #{bo.keyword}, '%') ))
AND o.external_order_no LIKE CONCAT('%', #{bo.keyword}, '%')
AND (o.cargo_order_no LIKE CONCAT('%', #{bo.keyword}, '%') OR o.external_order_no LIKE CONCAT('%', #{bo.keyword}, '%') OR o.marks LIKE CONCAT('%', #{bo.keyword}, '%') OR o.shipment_codes LIKE CONCAT('%', #{bo.keyword}, '%') OR o.po_nos LIKE CONCAT('%', #{bo.keyword}, '%') OR o.container_no LIKE CONCAT('%', #{bo.keyword}, '%'))
AND o.cargo_order_no LIKE CONCAT('%', #{bo.cargoOrderNo}, '%')
AND o.external_order_no LIKE CONCAT('%', #{bo.externalOrderNo}, '%')
AND o.customer_id = #{bo.customerId}
AND o.customer_name LIKE CONCAT('%', #{bo.customerName}, '%')
AND o.consignee_name LIKE CONCAT('%', #{bo.consigneeName}, '%')
AND o.business_type_id IN #{item}
AND o.channel_id IN #{item}
AND o.platform_id IN #{item}
AND o.customer_service_id IN #{item}
AND o.inbound_warehouse_id IN #{item}
AND o.order_source IN #{item}
AND o.address_type IN #{item}
AND o.platform_warehouse_code LIKE CONCAT('%', #{bo.platformWarehouseCode}, '%')
AND o.group_code LIKE CONCAT('%', #{bo.groupCode}, '%')
AND o.city LIKE CONCAT('%', #{bo.city}, '%')
AND o.state = #{bo.state}
AND o.zip_code LIKE CONCAT('%', #{bo.zipCode}, '%')
AND o.container_no LIKE CONCAT('%', #{bo.containerNo}, '%')
AND COALESCE(br.current_node, o.fulfillment_status) IN #{item}
AND o.billing_status IN #{item}
AND o.pre_outbound_status IN #{item}
AND o.outbound_order_status IN #{item}
AND o.pod_status IN #{item}
AND o.exception_flag IN #{item}
AND o.transfer_flag IN #{item}
AND o.outbound_batch_no LIKE CONCAT('%', #{bo.outboundBatchNo}, '%')
AND o.earliest_dw_time >= #{bo.beginEarliestDwTime} AND o.earliest_dw_time <= #{bo.endEarliestDwTime} AND o.eta >= #{bo.beginEta} AND o.eta <= #{bo.endEta} AND o.ata >= #{bo.beginAta} AND o.ata <= #{bo.endAta} AND o.actual_arrival_time >= #{bo.beginActualArrivalTime} AND o.actual_arrival_time <= #{bo.endActualArrivalTime} AND o.actual_inbound_time >= #{bo.beginActualInboundTime} AND o.actual_inbound_time <= #{bo.endActualInboundTime} AND o.delivery_appointment_time >= #{bo.beginDeliveryAppointmentTime} AND o.delivery_appointment_time <= #{bo.endDeliveryAppointmentTime} AND o.actual_outbound_time >= #{bo.beginActualOutboundTime} AND o.actual_outbound_time <= #{bo.endActualOutboundTime} AND o.signed_time >= #{bo.beginSignedTime} AND o.signed_time <= #{bo.endSignedTime} AND o.create_time >= #{bo.beginCreateTime} AND o.create_time <= #{bo.endCreateTime} ORDER BY o.create_time DESC

SELECT COALESCE(br.current_node, o.fulfillment_status) AS status_key, COUNT(*) AS status_count FROM oms_cargo_order o LEFT JOIN biz_root br ON br.id = o.biz_root_id AND br.deleted = 0 WHERE o.deleted = 0 AND COALESCE(br.current_node, o.fulfillment_status) IS NOT NULL AND COALESCE(br.current_node, o.fulfillment_status) != ''
AND o.customer_id = #{bo.customerId}
AND o.inbound_warehouse_id = #{bo.inboundWarehouseId}
GROUP BY COALESCE(br.current_node, o.fulfillment_status)
